// Count CRM campaign readiness indicators without asserting recipient eligibility.
const rows=$input.all().map(x=>x.json).filter(x=>x&&Object.keys(x).length);
if(rows.some(x=>x.error))return [{json:{source:'EspoCRM',readable:false,reason:'CRM_API_ERROR',
 campaignCount:0,activeCount:0,providerCount:0,preview:[]}}];
const seen=new Set(),preview=[];let activeCount=0,providerCount=0,templateReady=0;
for(const c of rows){
 if(typeof c.id!=='string'||!c.id||seen.has(c.id))return [{json:{source:'EspoCRM',readable:false,reason:'INVALID_DUPLICATE_ESPOCRM_CAMPAIGN',campaignCount:0,activeCount:0,providerCount:0,preview:[]}}];
 seen.add(c.id);
 if(c.status==='Active')activeCount++;
 if(String(c.ageProvider||'').toLowerCase().includes('chatwoot'))providerCount++;
 if(c.ageTemplateName&&c.ageTemplateLanguage)templateReady++;
 if(preview.length<15&&c.status==='Active')preview.push({
  id:c.id,name:typeof c.name==='string'?c.name.slice(0,75):null,
  providerConfigured:String(c.ageProvider||'').toLowerCase().includes('chatwoot'),
  templateConfigured:Boolean(c.ageTemplateName&&c.ageTemplateLanguage)
 });
}
return [{json:{source:'EspoCRM',readable:true,campaignCount:rows.length,activeCount,providerCount,
 templateConfiguredCount:templateReady,preview,recipientPolicyVerified:false,
 campaignWindowVerified:false,crmRetryPolicyVerified:false}}];

const rows=$input.all().map(x=>x.json).filter(x=>x&&Object.keys(x).length);
if(rows.some(x=>x.error))return [{json:{source:'Chatwoot',readable:false,reason:'CHATWOOT_API_ERROR',
 campaignCount:0,whatsAppOneOffCount:0,processing:0,completed:0}}];
const seen=new Set();let whatsAppOneOffCount=0,processing=0,completed=0;
for(const c of rows){
 const id=Number(c.id);
 if(!Number.isSafeInteger(id)||id<=0||seen.has(id))return [{json:{source:'Chatwoot',readable:false,reason:'INVALID_DUPLICATE_CHATWOOT_CAMPAIGN',campaignCount:0,whatsAppOneOffCount:0,processing:0,completed:0}}];
 seen.add(id);
 if(c.campaign_type==='one_off'&&c.inbox?.channel_type==='Channel::Whatsapp'){
  whatsAppOneOffCount++;
  if(c.campaign_status==='processing')processing++;
  if(c.campaign_status==='completed')completed++;
 }
}
return [{json:{source:'Chatwoot',readable:true,campaignCount:rows.length,
 whatsAppOneOffCount,processing,completed,crmBatchMappingVerified:false,providerReceiptsVerified:false}}];

// One read-only 6-hour report replacing WF-01/02/04/05/06. Never a sending decision.
const crm=$('Summarize EspoCRM Campaigns').first().json;
const chat=$('Summarize Chatwoot Campaigns').first().json;
const portfolioRows=$('Data Table - Read Portfolio (Max 51)').all().map(i=>i.json).filter(x=>x&&Object.keys(x).length);
const events=$input.all().map(i=>i.json).filter(x=>x&&Object.keys(x).length);
const blockers=[];
if(!crm.readable)blockers.push('ESPOCRM_API_UNAVAILABLE');
if(!chat.readable)blockers.push('CHATWOOT_API_UNAVAILABLE');
if(portfolioRows.some(x=>x.error))blockers.push('PORTFOLIO_DATA_TABLE_UNAVAILABLE');
if(events.some(x=>x.error))blockers.push('EVENT_DATA_TABLE_UNAVAILABLE');
if(portfolioRows.length===0)blockers.push('NO_PORTFOLIO_CONTROL_ROWS');
if(portfolioRows.length>50)blockers.push('PORTFOLIO_TABLE_SCAN_LIMIT_EXCEEDED');
if(events.length>3000)blockers.push('EVENT_TABLE_SCAN_LIMIT_EXCEEDED');
const now=Date.now(),seen=new Set(),summary=[];
const recent=(value,h)=>{const t=Date.parse(value);return Number.isFinite(t)&&t<=now&&now-t<=h*3600000;};
for(const x of portfolioRows.filter(x=>!x.error).slice(0,50)){
 const id=String(x.portfolioId||'').trim(),holds=[];
 if(!id||seen.has(id))holds.push('INVALID_OR_DUPLICATE_PORTFOLIO_ID');
 seen.add(id);
 if(x.masterSendingEnabled!==true)holds.push('MASTER_DISABLED');
 if(x.operatorLiveApproved!==true)holds.push('OPERATOR_APPROVAL_NOT_VERIFIED');
 if(x.providerAnalyticsVerified!==true)holds.push('ANALYTICS_NOT_VERIFIED');
 if(x.accountHealthVerified!==true)holds.push('ACCOUNT_HEALTH_NOT_VERIFIED');
 if(!Number.isSafeInteger(x.messagingTier)||x.messagingTier<=0||!recent(x.tierVerifiedAt,24))holds.push('TIER_UNKNOWN_OR_STALE');
 if(!recent(x.qualityVerifiedAt,24))holds.push('QUALITY_UNKNOWN_OR_STALE');
 if(x.externalUsageUnknown!==false||!Number.isSafeInteger(x.externalUnique24h)||x.externalUnique24h<0||
     !recent(x.externalUsageVerifiedAt,24))holds.push('EXTERNAL_USAGE_UNKNOWN_OR_STALE');
 if(x.unresolvedCycle!==false||String(x.activeCycleId||'').trim())holds.push('UNRESOLVED_CYCLE');
 if(x.priorCycleHistoryVerified!==true)holds.push('PRIOR_CYCLE_HISTORY_NOT_VERIFIED');
 if(x.lastVerifiedBatchCompletedAt){
  const t=Date.parse(x.lastVerifiedBatchCompletedAt);
  if(!Number.isFinite(t)||t>now||now-t<26*3600000)holds.push('GLOBAL_26_HOUR_GAP_OR_INVALID_COMPLETION');
 }
 if(!Number.isSafeInteger(x.rollingReserved24h)||x.rollingReserved24h<0)holds.push('RESERVATION_LEDGER_NOT_VERIFIED');
 const capacity=Number.isSafeInteger(x.messagingTier)&&Number.isSafeInteger(x.externalUnique24h)&&Number.isSafeInteger(x.rollingReserved24h)?
   Math.max(0,x.messagingTier-x.externalUnique24h-x.rollingReserved24h):null;
 if(capacity===0)holds.push('NO_RECORDED_HEADROOM');
 holds.push('DATA_TABLE_NOT_ATOMIC_SEND_AUTHORITY','LIVE_META_CAPACITY_UNVERIFIED');
 summary.push({portfolioId:id||null,recordedTier:x.messagingTier??null,estimatedHeadroom:capacity,holds});
}
const policies={
 '131050':'MARKETING_OPT_OUT_NO_AUTO_RETRY',
 '131049':'RECIPIENT_MARKETING_HOLD_RETAIN_EXISTING_CRM_POLICY',
 '131048':'QUALITY_RESTRICTION_PAUSE_AND_REVIEW',
 '131026':'AMBIGUOUS_UNDELIVERABLE_NOT_UNREGISTERED',
 '130472':'MARKETING_EXPERIMENT_REVIEW',
 '132015':'TEMPLATE_QUALITY_REVIEW'
};
const errorCounts=new Map(),stateCounts=new Map();let recordedRecentErrors=0;
if(events.length<=3000&&!events.some(x=>x.error)){
 for(const e of events){
  if(!e||Object.keys(e).length===0)continue;
  const n=e.count==null?1:Number(e.count);
  if(!Number.isSafeInteger(n)||n<0){blockers.push('INVALID_RECORDED_EVENT_COUNT');continue;}
  const state=String(e.state||'UNKNOWN');
  stateCounts.set(state,(stateCounts.get(state)||0)+n);
  const t=Date.parse(e.occurredAt),code=String(e.errorCode||'');
  if(/^[0-9]{5,6}$/.test(code)&&Number.isFinite(t)&&t<=now&&now-t<=30*86400000){
   errorCounts.set(code,(errorCounts.get(code)||0)+n);recordedRecentErrors++;
  }
 }
}
const errorByCode=[...errorCounts].map(([code,count])=>({code,count,policy:policies[code]||'REVIEW'}));
const hardOptoutCount=errorCounts.get('131050')||0;
if(hardOptoutCount>0)blockers.push('RECORDED_MARKETING_OPTOUT_REQUIRES_SOURCE_VERIFICATION');
blockers.push('RECIPIENT_CONSENT_AND_RETRY_NOT_VERIFIED','TEMPLATE_APPROVAL_NOT_VERIFIED',
 'SUNDAY_WINDOW_MIN_GAP_NOT_VERIFIED','SEPARATE_DAILY_DELIVERED_AND_ATTEMPT_CAPS_NOT_VERIFIED',
 'IMMUTABLE_BATCH_MAPPING_NOT_VERIFIED','NO_ATOMIC_SENDING_GATE');
return [{json:{
 checkedAt:new Date().toISOString(),cadence:'EVERY_6_HOURS',mode:'DRY_RUN',decision:'HOLD',
 crm:{readable:crm.readable,campaignCount:crm.campaignCount||0,activeCount:crm.activeCount||0,
  providerCount:crm.providerCount||0,templateConfiguredCount:crm.templateConfiguredCount||0,preview:crm.preview||[]},
 chatwoot:{readable:chat.readable,campaignCount:chat.campaignCount||0,
  whatsAppOneOffCount:chat.whatsAppOneOffCount||0,processing:chat.processing||0,completed:chat.completed||0},
 portfolio:{count:summary.length,observations:summary,complete:portfolioRows.length<=50&&!portfolioRows.some(x=>x.error)},
 events:{readable:events.length<=3000&&!events.some(x=>x.error)&&!blockers.includes('INVALID_RECORDED_EVENT_COUNT'),
  recordedRows:events.length,recentErrorRecords:recordedRecentErrors,
  recordedFailureCodes:errorByCode,recordedStates:[...stateCounts].map(([state,count])=>({state,count})),
  providerEventIngestionEnabled:false},
 blockers:[...new Set(blockers)],sourceOfTruth:'Read-only observations; official provider receipts and portfolio external usage not verified',
 canSend:false,createdCampaigns:0,crmEventsWritten:0,analyticsCapabilityNotCheckedByThisWorkflow:true
}}];
